window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[230]={"id":"230","numero":230,"titre":"Douleur thoracique aiguë","objectifs":[{"id":"230-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’uune douleur thoracique aiguë","contenu":"<p>La <span class=\"kw-def\">douleur thoracique aiguë</span> est une douleur ressentie dans la région du thorax, d'installation récente. C'est un <strong>motif de recours très fréquent aux urgences</strong> : l'enjeu n'est pas de poser d'emblée un diagnostic précis, mais d'<strong>éliminer en priorité une <span class=\"kw-alerte\">urgence</span> vitale</strong>.</p>\n      <p>Les structures thoraciques susceptibles d'être <strong>douloureuses</strong> sont :</p>\n      <ul>\n        <li>la <span class=\"kw-clinique\">paroi</span> — côtes, muscles, articulations chondro-costales ;</li>\n        <li>les <span class=\"kw-clinique\">enveloppes séreuses</span> — plèvre, péricarde ;</li>\n        <li>le <span class=\"kw-clinique\">cœur</span> ;</li>\n        <li>l'<span class=\"kw-clinique\">œsophage</span> et l'<span class=\"kw-clinique\">aorte</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le <strong>parenchyme pulmonaire ne fait pas mal</strong> — il n'est pas innervé pour la douleur. Seules les pathologies pulmonaires survenant <strong>au contact de la plèvre</strong> sont éventuellement sources de <span class=\"kw-clinique\">douleur thoracique</span>.\n      </div>\n      <p>Les <strong>3 causes les plus fréquentes</strong> de <span class=\"kw-clinique\">douleur thoracique</span> sont le <span class=\"kw-etio\">syndrome coronarien aigu</span>, les <span class=\"kw-etio\">douleurs œsophagiennes</span> et les <span class=\"kw-etio\">douleurs psychogènes</span>.</p>","frequence":0},{"id":"230-2","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir rechercher une détresse vitale devant une douleur thoracique","contenu":"<p>Devant toute <span class=\"kw-clinique\">douleur thoracique</span>, la <strong>première étape</strong> — avant même de chercher la cause — est de <strong>rechercher une <span class=\"kw-alerte\">détresse vitale</span></strong> par un examen rapide et systématisé. Trois territoires sont explorés.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Détresse</span></th><th>Signes à rechercher</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Détresse respiratoire</span></td>\n            <td>\n              <strong>Fréquence :</strong> <span class=\"kw-clinique\">polypnée</span> <span class=\"kw-chiffre\">&gt; 30/min</span> ou <span class=\"kw-clinique\">bradypnée</span> <span class=\"kw-chiffre\">&lt; 10/min</span> (voire pause respiratoire)<br>\n              <strong>Lutte :</strong> <span class=\"kw-clinique\">tirage</span> par mise en jeu des muscles respiratoires accessoires<br>\n              <strong>Retentissement :</strong> <span class=\"kw-clinique\">sueurs</span> ; <span class=\"kw-clinique\">cyanose</span> ; <span class=\"kw-clinique\">désaturation</span> (<span class=\"kw-chiffre\">SpO₂ &lt; 90 %</span>) ; encéphalopathie respiratoire\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Détresse hémodynamique</span></td>\n            <td>\n              <strong>Arrêt circulatoire :</strong> <span class=\"kw-clinique\">pouls carotidien</span> ou fémoral non perçu, patient inconscient<br>\n              <strong>État de <span class=\"kw-alerte\">choc</span> :</strong> collapsus avec hypoperfusion périphérique ; <span class=\"kw-clinique\">hypotension</span> avec <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">marbrures</span> et <span class=\"kw-clinique\">oligurie</span><br>\n              <strong>Autres :</strong> signes de <span class=\"kw-clinique\">cœur pulmonaire</span> ; <span class=\"kw-clinique\">pouls paradoxal</span> (<span class=\"kw-def\">dépression</span> du pouls à l'inspiration profonde)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Atteinte neurologique</span></td>\n            <td>Troubles de la conscience : <span class=\"kw-clinique\">confusion</span> ; <span class=\"kw-clinique\">agitation</span> ; <span class=\"kw-clinique\">convulsions</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> La présence d'<strong>un seul</strong> de ces signes impose une prise en charge immédiate en <strong>SAUV / <span class=\"kw-alerte\">réanimation</span></strong>, sans attendre les résultats paracliniques.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"230-3","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les signes de gravité imposant des décisions thérapeutiques tiques immédiates","contenu":"<p>Les <span class=\"kw-alerte\">signes de gravité</span> d'une <span class=\"kw-clinique\">douleur thoracique</span> sont les signes de <strong><span class=\"kw-alerte\">détresse vitale</span></strong> (respiratoire, hémodynamique, neurologique). Leur présence <strong>court-circuite la démarche diagnostique</strong> : on ne peut plus attendre les examens, des <strong>décisions thérapeutiques immédiates</strong> s'imposent.</p>\n      <p><strong>Mise en condition immédiate</strong>, menée en parallèle de l'évaluation :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">scope</span> <span class=\"kw-bio\">ECG</span> continu + monitorage de la <span class=\"kw-clinique\">pression artérielle</span> et de la <span class=\"kw-bio\">SpO₂</span> ;</li>\n        <li>pose d'une <strong>voie veineuse périphérique</strong> ;</li>\n        <li><span class=\"kw-ttt\">oxygénothérapie</span> en cas de désaturation ;</li>\n        <li>prise en charge en <strong>SAUV</strong>, à proximité immédiate d'un chariot d'<span class=\"kw-alerte\">urgence</span> et d'un <span class=\"kw-ttt\">défibrillateur</span>.</li>\n      </ul>\n      <p>Certains <span class=\"kw-alerte\">signes de gravité</span> orientent vers une <strong>décision thérapeutique spécifique et urgente</strong> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Signe de gravité</span></th><th>Décision immédiate</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Arrêt circulatoire</span> (pouls non perçu, inconscience)</td><td><span class=\"kw-ttt\">Réanimation cardio-pulmonaire</span> ; appel du réanimateur</td></tr>\n          <tr><td><span class=\"kw-clinique\">Pouls paradoxal</span> + <span class=\"kw-clinique\">turgescence jugulaire</span> + <span class=\"kw-clinique\">hypotension</span> (<span class=\"kw-alerte\">tamponnade</span>)</td><td><span class=\"kw-ttt\">Drainage péricardique</span> en <span class=\"kw-alerte\">urgence</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Asymétrie tensionnelle</span>, abolition d'un pouls, <span class=\"kw-alerte\">choc</span> (<span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span> de type A)</td><td><span class=\"kw-ttt\">Chirurgie en urgence</span> ; <span class=\"kw-ci\">contre-indication absolue aux anticoagulants à dose curative</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">État de choc</span> / <span class=\"kw-clinique\">hypotension</span> persistante</td><td>Orientation en <span class=\"kw-alerte\">réanimation</span> ; traitement étiologique sans délai</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Principe.</strong> Devant une <span class=\"kw-clinique\">douleur thoracique</span> grave, la priorité est de <strong>traiter la <span class=\"kw-alerte\">menace</span> vitale</strong> et d'orienter vers le plateau technique adapté — le bilan étiologique complet vient ensuite.\n      </div>","frequence":0},{"id":"230-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","contenu":"<p>Devant une <span class=\"kw-clinique\">douleur thoracique</span>, après avoir écarté la <span class=\"kw-alerte\">détresse vitale</span>, la <strong>2ᵉ étape</strong> consiste à évoquer systématiquement les <strong>4 urgences cardio-vasculaires</strong>, regroupées sous le moyen mnémotechnique <span class=\"kw-def\">PIED</span> :</p>\n      <ul>\n        <li><strong>P</strong> — <span class=\"kw-etio\">Péricardite</span> ;</li>\n        <li><strong>I</strong> — <span class=\"kw-etio\">Infarctus</span> (<span class=\"kw-etio\">syndrome coronarien aigu</span>) ;</li>\n        <li><strong>E</strong> — <span class=\"kw-etio\">Embolie pulmonaire</span> ;</li>\n        <li><strong>D</strong> — <span class=\"kw-etio\">Dissection aortique</span>.</li>\n      </ul>\n      <p>L'<strong>analyse sémiologique de la douleur</strong> oriente d'emblée — distinguer une douleur <strong><span class=\"kw-etio\">ischémique</span></strong> (cœur) d'une douleur <strong>non <span class=\"kw-etio\">ischémique</span></strong> :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Douleur <span class=\"kw-etio\">ischémique</span></th><th>Douleur non <span class=\"kw-etio\">ischémique</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Caractéristiques</strong></td><td><span class=\"kw-clinique\">Constriction</span>, <span class=\"kw-clinique\">pesanteur</span>, brûlure</td><td>Acérée, en coup de poignard, augmentée par la respiration</td></tr>\n          <tr><td><strong>Siège</strong></td><td>Rétrosternal ; médiothoracique ; irradiant cou, épaules, avant-bras, mâchoire ; associé à <span class=\"kw-clinique\">sueurs</span> et <span class=\"kw-clinique\">nausées</span></td><td>Sous-mammaire gauche ; hémithorax gauche ; punctiforme (montré du doigt) ; dorsal (<span class=\"kw-etio\">dissection</span>)</td></tr>\n          <tr><td><strong>Facteurs déclenchants</strong></td><td>Effort ; stress ; énervement ; temps froid</td><td>Après la fin de l'effort ; soulagement par l'effort ; provoquée par un mouvement particulier du corps</td></tr>\n          <tr><td><strong>Durée</strong></td><td>Minutes</td><td>Secondes, ou heures (en l'absence d'élévation des <span class=\"kw-bio\">troponines</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Chaque <span class=\"kw-alerte\">urgence</span> a un <strong>profil clinique évocateur</strong> qu'il faut savoir reconnaître :</p>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-etio\">SCA</span> (<span class=\"kw-clinique\">infarctus</span>)</th><th><span class=\"kw-alerte\"><span class=\"kw-etio\">Dissection</span> aortique</span></th><th><span class=\"kw-etio\">Embolie pulmonaire</span></th><th>Péricardite</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td><span class=\"kw-etio\">FDR cardio-vasculaires</span></td><td>FDRCV, notamment <span class=\"kw-etio\">HTA</span></td><td>Âge, <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-ttt\">chirurgie</span> récente, néoplasie</td><td>Sujet jeune, contage <span class=\"kw-etio\">viral</span></td></tr>\n          <tr><td><strong>Mode de survenue</strong></td><td>Brutal</td><td>Brutal</td><td>Progressif, associé à une <span class=\"kw-clinique\">dyspnée</span></td><td>Aigu</td></tr>\n          <tr><td><strong>Horaire</strong></td><td>Effort, repos</td><td>Repos</td><td>Repos</td><td>Inspiration, décubitus</td></tr>\n          <tr><td><strong>Localisation, <span class=\"kw-clinique\">irradiation</span></strong></td><td>Rétrosternale, épigastrique, mâchoire, bras, interscapulaire</td><td>Rétrosternale, <span class=\"kw-clinique\">transfixiante</span></td><td>Latéro- ou basithoracique</td><td>Rétrosternale</td></tr>\n          <tr><td><strong>Type</strong></td><td><span class=\"kw-clinique\">Constrictive</span>, brûlure</td><td><span class=\"kw-clinique\">Coup de poignard</span></td><td>—</td><td><span class=\"kw-clinique\">Constrictive</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Plaintes cardinales.</strong> Quelle que soit l'<span class=\"kw-alerte\">urgence</span> évoquée, 4 plaintes sont systématiquement renseignées : <strong><span class=\"kw-clinique\">douleur thoracique</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">syncope</span>, <span class=\"kw-clinique\">palpitations</span></strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 235 — Péricardite aiguë · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":1},{"id":"230-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie clinique fonctionnelle et physique de le dissection aortique","contenu":"<p>La <span class=\"kw-etio\">dissection aortique</span> est une <span class=\"kw-alerte\">urgence</span> rare mais gravissime : une <strong><span class=\"kw-alerte\">rupture</span> de l'intima</strong> crée une porte d'entrée, le sang s'engouffre dans un <span class=\"kw-def\">faux chenal</span> qui clive la média. Le faux chenal peut s'étendre (sens antérograde ou rétrograde), atteindre les collatérales de l'aorte, et surtout exposer à la <span class=\"kw-alerte\">rupture aortique</span> mortelle.</p>\n      <p><strong><span class=\"kw-def\">Terrain</span> et facteurs favorisants :</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">HTA ancienne</span> et <span class=\"kw-etio\">athérome</span> — sujet âgé, en général <span class=\"kw-chiffre\">&gt; 60 ans</span> ;</li>\n        <li><span class=\"kw-etio\">syndrome de Marfan</span> ou d'<span class=\"kw-etio\">Ehlers-Danlos</span> — sujet plus jeune ;</li>\n        <li>antécédent familial de maladie aortique ;</li>\n        <li>anévrisme de l'aorte thoracique, valvulopathie aortique connue ;</li>\n        <li>antécédent de <span class=\"kw-ttt\">chirurgie</span> aortique.</li>\n      </ul>\n      <p><strong>Signes fonctionnels — la douleur :</strong> début thoracique <strong>aigu et brutal</strong>, <strong>intense</strong>, à type de <span class=\"kw-clinique\">déchirement</span>, en <span class=\"kw-clinique\">coup de poignard</span> (<strong>transfixiante</strong>) — irradiant dans le <strong>dos</strong>, <span class=\"kw-clinique\">migratrice</span>, descendant vers les lombes et les membres inférieurs, parfois accompagnée d'une <span class=\"kw-clinique\">syncope</span>.</p>\n      <p><strong>Signes physiques :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">asymétrie tensionnelle</span> (différence <span class=\"kw-chiffre\">&gt; 20 mmHg</span>), <span class=\"kw-clinique\">abolition d'un pouls</span> ;</li>\n        <li><span class=\"kw-clinique\">souffle d'insuffisance aortique</span> (dans <span class=\"kw-chiffre\">50 %</span> des dissections de type A) ;</li>\n        <li>poussée d'<span class=\"kw-clinique\">HTA</span>, ou au contraire <span class=\"kw-alerte\">hypotension / choc</span>.</li>\n      </ul>\n      <p><strong>Complications parfois révélatrices</strong> (par extension du faux chenal aux collatérales) :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">déficit neurologique</span> (<span class=\"kw-etio\">AVC</span>), <span class=\"kw-clinique\">infarctus</span> médullaire (syndrome médullaire aigu) ;</li>\n        <li><span class=\"kw-alerte\">hémopéricarde avec tamponnade</span> ;</li>\n        <li><span class=\"kw-clinique\">infarctus</span> mésentérique, <span class=\"kw-alerte\">ischémie aiguë</span> d'un membre, <span class=\"kw-etio\">insuffisance rénale aiguë</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span> de probabilité clinique de <span class=\"kw-etio\">dissection</span></th><th>Cotation</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span> évocateur :</strong> <span class=\"kw-clinique\">syndrome de Marfan</span> ; ATCD familial de maladie aortique ; anévrisme ou valvulopathie aortique connus ; ATCD de <span class=\"kw-ttt\">chirurgie</span> aortique</td><td><span class=\"kw-chiffre\">1 point</span></td></tr>\n          <tr><td><strong>Douleur évocatrice :</strong> <span class=\"kw-clinique\">douleur thoracique</span>, dorsale ou abdominale, de début brutal, intense, à type de déchirement</td><td><span class=\"kw-chiffre\">1 point</span></td></tr>\n          <tr><td><strong>Signes à l'examen :</strong> abolition d'un pouls ; <span class=\"kw-clinique\">asymétrie</span> tensionnelle ; déficit neurologique focal ; insuffisance aortique ; <span class=\"kw-clinique\">hypotension</span> ou <span class=\"kw-alerte\">choc</span></td><td><span class=\"kw-chiffre\">1 point</span></td></tr>\n        </tbody>\n      </table>\n      <p>Probabilité clinique <strong>faible</strong> si <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">0 ou 1</span>, <strong>forte</strong> si score <span class=\"kw-chiffre\">2 ou 3</span>.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Piège majeur — <span class=\"kw-ci\">contre-indication</span>.</strong> En cas de <span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span>, les <span class=\"kw-ci\">anticoagulants à dose curative sont formellement contre-indiqués</span>. C'est tout l'enjeu de ne pas confondre une dissection avec un <span class=\"kw-etio\">SCA</span> ou une <span class=\"kw-etio\">embolie pulmonaire</span>, qui eux seraient anticoagulés.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Classification</span> de Stanford</strong> (référence) — <strong>type A</strong> : la <span class=\"kw-etio\">dissection</span> intéresse l'aorte ascendante → <strong><span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span></strong> (risque de <span class=\"kw-alerte\">rupture</span>, tamponnade, insuffisance aortique massive). <strong>Type B</strong> : la dissection n'intéresse pas l'aorte ascendante → pas de chirurgie urgente en l'absence de complication, <strong>contrôle de la pression artérielle</strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-def\">HTA</span> · 233 — Valvulopathie</em></p>","frequence":1},{"id":"230-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","contenu":"<p>La démarche diagnostique devant une <span class=\"kw-clinique\">douleur thoracique</span> est <strong>hiérarchisée</strong> et toujours conduite dans le même ordre.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1 — <span class=\"kw-alerte\">Détresse</span> vitale</strong></td><td>Recherche systématique d'une <span class=\"kw-alerte\">détresse</span> respiratoire, hémodynamique ou neurologique</td></tr>\n          <tr><td><strong>2 — Les 4 urgences</strong></td><td>Évoquer <span class=\"kw-def\">PIED</span> : Péricardite, <span class=\"kw-clinique\">Infarctus</span>, <span class=\"kw-etio\">Embolie pulmonaire</span>, <span class=\"kw-etio\">Dissection</span> — puis les autres urgences (pleurésie, <span class=\"kw-etio\">pneumonie</span>, <span class=\"kw-etio\">pneumothorax</span>, <span class=\"kw-alerte\">rupture</span> œsophagienne, <span class=\"kw-etio\">pancréatite aiguë</span>, UGD compliqué, cholécystite, douleurs radiculaires)</td></tr>\n          <tr><td><strong>3 — Paraclinique</strong></td><td>\n            <strong>Systématique :</strong> <span class=\"kw-bio\">ECG 18 dérivations</span> ; <span class=\"kw-imagerie\">radiographie thoracique</span> en inspiration ; <span class=\"kw-bio\">SpO₂</span> ± <span class=\"kw-bio\">gaz du sang</span><br>\n            <strong>Orienté cardio :</strong> dosage des <span class=\"kw-bio\">troponines ultrasensibles</span> systématique<br>\n            <strong>Orienté EP :</strong> <span class=\"kw-bio\">D-dimères</span> selon la probabilité clinique\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cas particulier — démarche diagnostique de la <span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span></strong>, guidée par le <span class=\"kw-def\">score</span> de probabilité clinique :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Démarche</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Patient stable, probabilité faible</strong> (<span class=\"kw-def\">score</span> 0-1)</td><td><span class=\"kw-imagerie\">ETT/ETO</span> complétée par la <span class=\"kw-imagerie\">radiographie thoracique</span> (<span class=\"kw-radio\">élargissement médiastinal</span>) et le dosage des <span class=\"kw-bio\">D-dimères</span> (d'emblée très élevés)</td></tr>\n          <tr><td><strong>Patient stable, probabilité forte</strong> (<span class=\"kw-def\">score</span> 2-3)</td><td><span class=\"kw-imagerie\">ETO</span> — peut conduire à une <span class=\"kw-imagerie\">ETO</span> pré-opératoire au bloc, ou à un <span class=\"kw-imagerie\">angio-TDM thoracique</span></td></tr>\n          <tr><td><strong>Patient hémodynamiquement instable</strong></td><td><span class=\"kw-imagerie\">ETO</span> ou <span class=\"kw-imagerie\">angio-TDM thoracique</span> sans délai</td></tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-imagerie\">ETO</span> met en évidence le <strong><span class=\"kw-radio\">voile intimal</span></strong>, signe <span class=\"kw-alerte\">pathognomonique</span> de <span class=\"kw-etio\">dissection</span>. L'<span class=\"kw-imagerie\">angio-TDM</span> est souvent nécessaire au <span class=\"kw-def\">diagnostic positif</span> (surtout chez les patients instables) et à la planification chirurgicale (porte d'entrée, extension de la dissection, atteinte des troncs supra-aortiques, mésentériques ou rénaux).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/230/tdm-dissection-aortique-stanford-a.png\" alt=\"Angio-TDM thoracique en coupe axiale — dissection aortique de type A : double chenal de l'aorte ascendante\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Angio-TDM</span> thoracique, coupe axiale : <span class=\"kw-alerte\">dissection aortique</span> de <strong>type A</strong> (Stanford) — double contour au sein de la lumière de l'aorte ascendante (<span class=\"kw-radio\">voile intimal</span> séparant vrai et faux chenal). Source : fiche source EDN item 230 — <span class=\"kw-clinique\">Douleur thoracique</span> aiguë (Dissection aortique).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/230/tdm-dissection-aortique-stanford-b.png\" alt=\"Angio-TDM thoracique en coupe axiale — dissection aortique de type B : double chenal de l'aorte descendante\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Angio-TDM</span> thoracique, coupe axiale : dissection aortique de <strong>type B</strong> (Stanford) — double chenal limité à l'aorte descendante, l'aorte ascendante étant respectée. Source : fiche source EDN item 230 — <span class=\"kw-clinique\">Douleur thoracique</span> aiguë (Dissection aortique).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/230/classification-dissection-aortique-stanford-debakey.png\" alt=\"Schéma des classifications de Stanford et de DeBakey de la dissection aortique\" loading=\"lazy\">\n        <figcaption>Classifications de la dissection aortique. <strong>Stanford</strong> — type A : atteinte de l'aorte ascendante ; type B : aorte ascendante respectée. <strong>DeBakey</strong> — type I : porte d'entrée sur l'aorte ascendante avec extension à l'aorte descendante ; type II : limitée à l'aorte ascendante ; type III : porte d'entrée après l'artère sous-clavière gauche. Source : fiche source EDN item 230 — <span class=\"kw-clinique\">Douleur thoracique</span> aiguë (Dissection aortique).</figcaption>\n      </figure>","frequence":2},{"id":"230-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","contenu":"<p>L'<span class=\"kw-bio\">ECG</span> — 18 dérivations, réalisé en <span class=\"kw-alerte\">urgence</span> — est l'examen clé d'orientation. Chaque urgence a une signature électrique propre.</p>\n      <table >\n        <thead><tr><th>Urgence</th><th>Apport de l'<span class=\"kw-bio\">ECG</span></th><th>Anomalies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">SCA</span> (<span class=\"kw-clinique\">infarctus</span>)</strong></td><td>+++ (examen central)</td><td>Signes d'<span class=\"kw-clinique\">ischémie</span> : <span class=\"kw-alerte\">sus-décalage ST</span> ; sous-décalage ST ; anomalies de l'onde T</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Embolie pulmonaire</span></strong></td><td>++</td><td><span class=\"kw-clinique\">Tachycardie sinusale</span> ; bloc de branche droit ; onde T négative ; aspect <span class=\"kw-clinique\">S1Q3</span></td></tr>\n          <tr><td><strong>Péricardite</strong></td><td>++</td><td><span class=\"kw-clinique\">Sus-décalage ST concave</span> vers le haut, diffus (non systématisé) et <strong>sans miroir</strong> ; <span class=\"kw-clinique\">sous-décalage du PQ</span> ; en cas de <span class=\"kw-alerte\">tamponnade</span> : <strong><span class=\"kw-clinique\">microvoltage</span></strong> et <strong><span class=\"kw-clinique\">alternance électrique</span></strong> (variation d'amplitude des QRS 1 sur 2)</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\"><span class=\"kw-etio\">Dissection</span> aortique</span></strong></td><td>± (peu contributif)</td><td>Normal le plus souvent ; en cas d'extension à une artère coronaire : aspect de <span class=\"kw-etio\">SCA</span> (sous-ST, sus-ST ou inversion de l'onde T)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Un <span class=\"kw-bio\">ECG</span> d'allure de <span class=\"kw-etio\">SCA</span> n'élimine pas une <span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span> : la dissection peut <strong>s'étendre à une coronaire</strong> et mimer un <span class=\"kw-clinique\">infarctus</span> — d'où le risque d'anticoaguler à tort une dissection.\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/aortic-dissection","label":"Radiopaedia : Aortic dissection"}]},{"id":"230-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","contenu":"<p>La <span class=\"kw-imagerie\">radiographie thoracique</span>, réalisée en inspiration, fait partie du bilan <strong>systématique</strong>. Sa <strong>place</strong> est double : elle est surtout utile pour <strong>écarter les diagnostics différentiels</strong> (<span class=\"kw-etio\">pneumothorax</span>, pneumopathie, <span class=\"kw-etio\">épanchement pleural</span>) et peut apporter des signes d'orientation — mais elle est <strong>souvent normale</strong> dans les urgences cardio-vasculaires.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span></th><th><span class=\"kw-imagerie\">Radiographie thoracique</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">SCA</span> (<span class=\"kw-clinique\">infarctus</span>)</strong></td><td>Normale en règle (pas de signe spécifique) ; recherche de signes d'<span class=\"kw-etio\">insuffisance cardiaque</span></td></tr>\n          <tr><td><strong><span class=\"kw-alerte\"><span class=\"kw-etio\">Dissection</span> aortique</span></strong></td><td><span class=\"kw-radio\">Élargissement du médiastin supérieur</span> ++ ; ± <span class=\"kw-etio\">épanchement pleural</span> (hémothorax par <span class=\"kw-alerte\">rupture</span> de l'aorte thoracique) ; ± aspect de <span class=\"kw-radio\">double contour aortique</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Embolie pulmonaire</span></strong></td><td>Souvent normale ; signes inconstants et peu spécifiques</td></tr>\n          <tr><td><strong>Péricardite</strong></td><td>Normale en règle ; si <span class=\"kw-radio\">épanchement péricardique</span> abondant → <span class=\"kw-radio\">cardiomégalie avec <strong>cœur « en carafe »</strong></span> (silhouette symétrique triangulaire)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 360 — <span class=\"kw-imagerie\">Pneumothorax</span></em></p>","frequence":0},{"id":"230-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","contenu":"<p>Deux examens biologiques structurent le bilan : les <span class=\"kw-bio\">troponines ultrasensibles</span> et les <span class=\"kw-bio\">D-dimères</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span></th><th><span class=\"kw-bio\">Troponine</span> us</th><th><span class=\"kw-bio\">D-dimères</span> / autres</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">SCA</span> (<span class=\"kw-clinique\">infarctus</span>)</strong></td><td>Dosage systématique ; élévation avec <strong>cinétique</strong> — surtout contributive dans les <span class=\"kw-etio\">SCA</span> <strong>non ST+</strong></td><td>—</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\"><span class=\"kw-etio\">Dissection</span> aortique</span></strong></td><td>± (peut être élevée en cas d'extension coronaire)</td><td><span class=\"kw-bio\">D-dimères</span> d'emblée <strong>très élevés</strong></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Embolie pulmonaire</span></strong></td><td>Intérêt <strong>pronostique</strong> (souffrance du ventricule droit)</td><td><span class=\"kw-bio\">D-dimères</span> selon la probabilité clinique — bonne valeur prédictive négative</td></tr>\n          <tr><td><strong>Péricardite</strong></td><td>Élévation possible si <span class=\"kw-clinique\">myocardite</span> associée</td><td><span class=\"kw-def\">Syndrome inflammatoire</span> (<span class=\"kw-bio\">CRP</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Dans la <span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span>, le bilan <span class=\"kw-ttt\">biologique</span> requis comprend aussi : <span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatininémie</span> et <span class=\"kw-bio\">créatine-kinase</span> (recherche de rhabdomyolyse).</p>\n      <div class=\"callout callout-warn\">\n        <strong>Interprétation.</strong> Une <span class=\"kw-bio\">troponine</span> élevée signe une <strong>souffrance myocardique</strong> mais n'est pas spécifique du <span class=\"kw-etio\">SCA</span> (l'EP, la <span class=\"kw-etio\">dissection</span>, la myocardite l'élèvent aussi) — c'est la <strong>cinétique</strong> et le contexte qui comptent. Les <span class=\"kw-bio\">D-dimères</span> ont surtout une valeur <strong>d'exclusion</strong> : négatifs avec une probabilité clinique faible, ils écartent l'<span class=\"kw-etio\">embolie pulmonaire</span>.\n      </div>","frequence":0},{"id":"230-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la place de la coronarographie dans le diagnostic et les principes de prise en charge du syndrome coronarien aigu","contenu":"<p>La <span class=\"kw-imagerie\">coronarographie</span> est l'examen de <strong>référence</strong> du <span class=\"kw-etio\">syndrome coronarien aigu</span> : examen invasif d'opacification des artères coronaires, elle a une <strong>double fonction</strong> — <strong>diagnostique</strong> (localiser la sténose ou l'occlusion coronaire responsable) et <strong>thérapeutique</strong> (<span class=\"kw-ttt\">revascularisation</span> par <span class=\"kw-ttt\">angioplastie</span> ± pose d'un <span class=\"kw-ttt\">stent</span> dans le même temps).</p>\n      <p>Schématiquement, sa place dépend du type de <span class=\"kw-etio\">SCA</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">SCA</span> avec sus-décalage ST</strong> — <span class=\"kw-imagerie\">coronarographie</span> en <strong><span class=\"kw-alerte\">urgence</span></strong>, le plus rapidement possible, en vue d'une <span class=\"kw-ttt\">reperfusion</span> :\n          <ul>\n            <li>Délai <strong>ECG → guide d'angioplastie ≤ <span class=\"kw-chiffre\">120 min</span></strong> → <span class=\"kw-ttt\">angioplastie primaire</span> recommandée</li>\n            <li>Délai <strong>&gt; <span class=\"kw-chiffre\">120 min</span></strong> → <strong><span class=\"kw-ttt\">fibrinolyse</span></strong> privilégiée (sauf CI, sauf symptômes &gt; 12 h), suivie d'une <span class=\"kw-ttt\">angioplastie de sauvetage</span> si pas de reperfusion, ou différée dans les <span class=\"kw-chiffre\">24 h</span> si reperfusion</li>\n            <li>Au-delà de <span class=\"kw-chiffre\">12 h</span> : angioplastie primaire si douleur persistante, instabilité hémodynamique ou rythmique ; à considérer jusqu'à <span class=\"kw-chiffre\">48 h</span></li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-etio\">SCA</span> sans sus-décalage ST</strong> — <span class=\"kw-imagerie\">coronarographie</span> généralement dans les <span class=\"kw-chiffre\">24 h</span> ; <strong>&lt; <span class=\"kw-chiffre\">2 h</span></strong> si SCA non ST+ réfractaire au traitement médical (patient toujours douloureux).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Les fiches sources de l'item 230 ne détaillent pas la prise en charge du <span class=\"kw-etio\">syndrome coronarien aigu</span> — c'est l'objet de l'item dédié. Kevin enrichira les modalités précises (délais de <span class=\"kw-ttt\">reperfusion</span>, traitement antithrombotique) à partir de l'item 339.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":1},{"id":"230-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la place de l’échocardiographie","contenu":"<p>L'<span class=\"kw-imagerie\">échocardiographie transthoracique (ETT)</span> est un examen <strong>non invasif, réalisable au lit du patient</strong>, précieux dans le bilan d'une <span class=\"kw-clinique\">douleur thoracique</span> aiguë. L'<span class=\"kw-imagerie\">échocardiographie transœsophagienne (ETO)</span> est plus performante pour explorer l'aorte.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span></th><th>Apport de l'<span class=\"kw-imagerie\">échocardiographie</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\"><span class=\"kw-etio\">Dissection</span> aortique</span></strong></td><td><span class=\"kw-imagerie\">ETO</span> surtout : visualisation du <strong><span class=\"kw-radio\">voile intimal</span></strong>, signe <span class=\"kw-alerte\">pathognomonique</span> ; chez un patient stable à faible probabilité, l'<span class=\"kw-imagerie\">ETT</span>/<span class=\"kw-imagerie\">ETO</span> peut poser le diagnostic</td></tr>\n          <tr><td><strong>Péricardite</strong></td><td>Recherche et quantification d'un <span class=\"kw-radio\">épanchement péricardique</span> ; <span class=\"kw-def\">dépistage</span> d'une <span class=\"kw-alerte\">tamponnade</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Embolie pulmonaire</span></strong></td><td>Recherche d'un retentissement sur le <span class=\"kw-clinique\">cœur droit</span> (dilatation du ventricule droit, cœur pulmonaire aigu) — intérêt pronostique</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">SCA</span> (<span class=\"kw-clinique\">infarctus</span>)</strong></td><td>Recherche de <span class=\"kw-clinique\">troubles de la cinétique segmentaire</span> ; évaluation de la fonction ventriculaire gauche</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 235 — Péricardite aiguë</em></p>","frequence":0},{"id":"230-12","rang":"B","rubrique":"Étiologies","titre":"Devant un angor d’effort, connaître les principales causes d’angor fonctionnel","contenu":"<p>L'<span class=\"kw-def\">angor fonctionnel</span> est un <span class=\"kw-clinique\">angor</span> d'effort survenant <strong>sans sténose coronaire significative</strong> : il résulte d'une <strong>inadéquation entre les apports et les besoins en oxygène</strong> du myocarde. Il s'oppose à l'angor organique (<span class=\"kw-etio\">athéromateux</span>).</p>\n      <p>Devant un <span class=\"kw-clinique\">angor</span> d'effort, les principales causes d'angor fonctionnel — entrant dans le cadre des <strong>douleurs chroniques de cause cardiaque</strong> — sont :</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Anémie</span></td><td>Baisse du transport de l'oxygène</td></tr>\n          <tr><td><span class=\"kw-etio\">Tachycardies</span> (ex. <span class=\"kw-etio\">fibrillation atriale</span>)</td><td>Augmentation des besoins myocardiques + raccourcissement de la diastole</td></tr>\n          <tr><td><span class=\"kw-etio\">Hyperthyroïdie</span></td><td>Augmentation du débit cardiaque et de la consommation d'oxygène</td></tr>\n          <tr><td><span class=\"kw-etio\">Rétrécissement aortique serré</span></td><td><span class=\"kw-clinique\">Angor</span> d'effort par obstacle à l'éjection ventriculaire</td></tr>\n          <tr><td><span class=\"kw-etio\">Cardiomyopathie hypertrophique</span></td><td>Douleur d'effort par inadéquation de la perfusion d'un myocarde épaissi</td></tr>\n          <tr><td><span class=\"kw-etio\">HTAP sévère</span></td><td>Souffrance <span class=\"kw-etio\">ischémique</span> du ventricule droit lorsque la pression intraventriculaire droite dépasse la pression de perfusion coronarienne</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 232 — <span class=\"kw-def\">Fibrillation atriale</span> · 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 233 — Valvulopathie</em></p>","frequence":0},{"id":"230-13","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","contenu":"<p>En dehors des 4 urgences cardio-vasculaires, de nombreuses causes <strong>thoraciques</strong> de douleur aiguë doivent être connues. Elles se répartissent par appareil.</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Causes et particularités sémiologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Respiratoire</strong></td>\n            <td>\n              <strong>Pleuro-pulmonaire :</strong> <span class=\"kw-etio\">pneumothorax</span> ; <span class=\"kw-etio\">épanchement pleural</span> ; <span class=\"kw-etio\">pneumopathie infectieuse</span> (douleur intense « en coup de poignard » de type pleural en cas de réaction pleurale)\n              <ul style=\"margin:4px 0 0;padding-left:18px\">\n                <li><span class=\"kw-etio\">Pneumothorax</span> — <span class=\"kw-clinique\">douleur de type pleural</span> (latéro-thoracique, majorée à l'inspiration).</li>\n                <li><span class=\"kw-clinique\">Tympanisme à la percussion</span> + <span class=\"kw-clinique\">abolition du murmure vésiculaire</span> du côté atteint.</li>\n                <li>Diagnostic : <span class=\"kw-imagerie\">radiographie thoracique</span> de face en <strong>inspiration</strong> (hyperclarté + ligne pleurale ; le cliché en expiration n'est plus recommandé).</li>\n              </ul><br>\n              <strong><span class=\"kw-etio\">Trachéobronchite aiguë</span> :</strong> <span class=\"kw-clinique\">brûlure respiratoire</span> à chaque mouvement, <strong>aggravée par la <span class=\"kw-clinique\">toux</span></strong>, initialement sèche ; cortège <span class=\"kw-etio\">viral</span> fréquent ; traitement symptomatique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Œsophagienne</strong></td>\n            <td>\n              <strong>RGO, œsophagite :</strong> peuvent <span class=\"kw-alerte\">simuler un SCA</span> — douleur <span class=\"kw-clinique\">constrictive</span> avec irradiation (le cœur et l'œsophage ont une innervation commune)<br>\n              <strong><span class=\"kw-etio\">Spasme œsophagien</span> :</strong> douleur d'<span class=\"kw-clinique\">allure angineuse</span>, souvent déclenchée par la <strong>déglutition</strong> ; <span class=\"kw-alerte\">calmée par les dérivés nitrés (piège !)</span> ou par le phloroglucinol<br>\n              <strong><span class=\"kw-etio\">Syndrome de Mallory-Weiss</span></strong><br>\n              <strong><span class=\"kw-alerte\">Rupture</span> de l'œsophage (<span class=\"kw-etio\">Boerhaave</span>) :</strong> <span class=\"kw-clinique\">douleur thoracique</span> + <span class=\"kw-clinique\">dyspnée</span> + <span class=\"kw-clinique\">emphysème sous-cutané</span> (crépitation neigeuse) ou pneumomédiastin\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Musculo-squelettique</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">Syndrome de Tietze</span> :</strong> inflammation du cartilage à la jonction du sternum et d'une ou plusieurs côtes — <span class=\"kw-alerte\">douleur reproduite par la palpation</span><br>\n              <strong>Osseuse :</strong> lésions sternales, <span class=\"kw-clinique\">arthralgies</span> chondro-costales ; fractures costales, parfois pathologiques (<span class=\"kw-etio\">métastases</span>, <span class=\"kw-etio\">myélome multiple</span>)<br>\n              <strong>Douleur musculo-ligamentaire</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Neurologique</strong></td>\n            <td><span class=\"kw-etio\">Zona intercostal</span> ; <span class=\"kw-etio\">tassement vertébral</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Toxique</span> — cocaïne</strong></td>\n            <td><span class=\"kw-etio\">SCA</span> voire <span class=\"kw-etio\">coronarospasme</span> (<span class=\"kw-clinique\">angor</span> de Prinzmetal) ; <span class=\"kw-etio\">myopéricardite</span> ; <span class=\"kw-etio\">pneumothorax</span> lié aux efforts inspiratoires (sniff)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une douleur œsophagienne (RGO, spasme) peut <strong>parfaitement mimer un <span class=\"kw-etio\">SCA</span></strong> et même être <strong>calmée par les dérivés <span class=\"kw-ttt\">nitrés</span></strong>. On ne retient jamais une cause œsophagienne <strong>avant d'avoir éliminé un <span class=\"kw-etio\">SCA</span></strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 360 — <span class=\"kw-imagerie\">Pneumothorax</span> · 154 — Infection bronchopulmonaire communautaire · 271 — RGO - hernie hiatale</em></p>","frequence":2},{"id":"230-14","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes extra-thoraciques de douleur thoracique","contenu":"<p>Une <span class=\"kw-clinique\">douleur thoracique</span> peut avoir une origine <strong>extra-thoracique</strong> — la connaître évite des explorations cardiaques inutiles, une fois les urgences écartées.</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Abdominale</strong> (douleur projetée)</td>\n            <td><span class=\"kw-etio\">Lithiase vésiculaire</span> ; <span class=\"kw-etio\">ulcère gastro-duodénal</span> ; <span class=\"kw-etio\">pancréatite aiguë</span> ; <span class=\"kw-etio\">appendicite sous-hépatique</span> ; <span class=\"kw-etio\">abcès sous-phrénique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Psychogène</strong></td>\n            <td><span class=\"kw-etio\">Douleurs psychogènes</span> — <strong>extrêmement fréquentes</strong>, accompagnées d'angoisse, dans un contexte névrotique</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les douleurs psychogènes sont l'une des <strong>3 causes les plus fréquentes</strong> de <span class=\"kw-clinique\">douleur thoracique</span> (avec le <span class=\"kw-etio\">SCA</span> et les douleurs œsophagiennes) — mais elles restent un <strong>diagnostic d'élimination</strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë · 358 — <span class=\"kw-def\">Pancréatite aiguë</span> · 277 — Lithiase biliaire · 272 — Ulcère gastroduodénal - gastrite</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Détresse</span> vitale <span class=\"q\">— avant tout diagnostic</span></strong></p><p>Prise en charge en <span class=\"kw-alerte\">SAUV / réanimation</span> sans attendre les résultats paracliniques</p><ul><li>Recherche systématique d'une <span class=\"kw-alerte\">détresse respiratoire</span>, <span class=\"kw-alerte\">hémodynamique</span> ou <span class=\"kw-alerte\">neurologique</span></li><li>Mise en condition : <span class=\"kw-clinique\">scope</span>, <span class=\"kw-bio\">ECG</span> continu, <span class=\"kw-bio\">SpO₂</span>, <span class=\"kw-ttt\">voie veineuse périphérique</span>, <span class=\"kw-ttt\">oxygénothérapie</span> si désaturation</li></ul><p><strong>Arrêt circulatoire</strong></p><p><span class=\"kw-ttt\">Réanimation cardio-pulmonaire</span> + appel du réanimateur</p><ul><li><span class=\"kw-clinique\">Pouls carotidien</span> ou fémoral non perçu, patient inconscient</li></ul><p><strong><span class=\"kw-alerte\">Tamponnade</span></strong></p><p><span class=\"kw-ttt\">Drainage péricardique</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li><span class=\"kw-clinique\">Pouls paradoxal</span> + <span class=\"kw-clinique\">turgescence jugulaire</span> + <span class=\"kw-alerte\">hypotension</span></li></ul><p><strong><span class=\"kw-alerte\"><span class=\"kw-etio\">Dissection</span> aortique</span> de type A</strong></p><p><span class=\"kw-ttt\">Chirurgie en urgence</span> · <span class=\"kw-ci\">anticoagulants à dose curative contre-indiqués</span></p><ul><li><span class=\"kw-clinique\">Asymétrie tensionnelle</span>, <span class=\"kw-clinique\">abolition d'un pouls</span>, <span class=\"kw-alerte\">choc</span></li></ul><p><strong><span class=\"kw-alerte\">SCA</span> avec sus-décalage ST</strong></p><p><span class=\"kw-imagerie\">Coronarographie</span> en <span class=\"kw-alerte\">urgence</span> le plus rapidement possible, en vue d'une <span class=\"kw-ttt\">reperfusion</span></p><ul><li><span class=\"kw-alerte\">Sus-décalage ST</span> persistant systématisé à l'<span class=\"kw-bio\">ECG</span></li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Détresse</span> vitale :</strong> <span class=\"kw-alerte\">SAUV / réanimation</span> sans délai, à proximité immédiate d'un chariot d'<span class=\"kw-alerte\">urgence</span> et d'un <span class=\"kw-ttt\">défibrillateur</span>.<br><strong>Une des 4 urgences cardio-vasculaires :</strong> orientation vers le <span class=\"kw-def\">plateau technique adapté</span> et traitement étiologique sans délai.<br><strong>Douleur d'allure non urgente :</strong> prise en charge ambulatoire envisageable, mais seulement <span class=\"kw-alerte\">après avoir éliminé un SCA</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Polypnée</span> <span class=\"kw-chiffre\">&gt; 30/min</span> ou <span class=\"kw-alerte\">bradypnée</span> <span class=\"kw-chiffre\">&lt; 10/min</span> ; <span class=\"kw-clinique\">tirage</span> ; <span class=\"kw-alerte\">désaturation</span> (<span class=\"kw-chiffre\">SpO₂ &lt; 90 %</span>)</li><li><span class=\"kw-alerte\">Arrêt circulatoire</span> : <span class=\"kw-clinique\">pouls carotidien</span> ou fémoral non perçu, patient inconscient</li><li><span class=\"kw-alerte\">État de choc</span> : <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">marbrures</span>, <span class=\"kw-clinique\">oligurie</span></li><li><span class=\"kw-clinique\">Pouls paradoxal</span> + <span class=\"kw-clinique\">turgescence jugulaire</span> → <span class=\"kw-alerte\">tamponnade</span></li><li><span class=\"kw-clinique\">Asymétrie tensionnelle</span> / <span class=\"kw-clinique\">abolition d'un pouls</span> → <span class=\"kw-alerte\">dissection aortique</span></li><li><span class=\"kw-alerte\">Troubles de la conscience</span> : <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">agitation</span>, <span class=\"kw-clinique\">convulsions</span></li></ul>","principes":"<p>La priorité est de <span class=\"kw-alerte\">traiter la menace vitale</span> et d'orienter vers le plateau technique adapté ; le bilan étiologique complet vient ensuite. <strong>Piège majeur :</strong> ne pas confondre une <span class=\"kw-etio\">dissection aortique</span> (où les <span class=\"kw-ci\">anticoagulants curatifs sont contre-indiqués</span>) avec un <span class=\"kw-etio\">SCA</span> ou une <span class=\"kw-etio\">embolie pulmonaire</span> (qui, eux, seraient anticoagulés).</p><p><strong><span class=\"kw-alerte\">SCA</span> (<span class=\"kw-clinique\">infarctus</span>)</strong></p><p>Modalités antithrombotiques précises détaillées dans l'item 339</p><ul><li><span class=\"kw-imagerie\">Coronarographie</span> = examen de référence, double fonction diagnostique et thérapeutique (<span class=\"kw-ttt\">angioplastie</span> ± <span class=\"kw-ttt\">stent</span>)</li><li><span class=\"kw-alerte\">SCA</span> <span class=\"kw-alerte\">avec sus-décalage ST</span> → <span class=\"kw-ttt\">reperfusion</span> en <span class=\"kw-alerte\">urgence</span>, le plus rapidement possible</li><li><span class=\"kw-alerte\">SCA</span> sans sus-décalage ST → <span class=\"kw-imagerie\">coronarographie</span> selon le niveau de risque</li></ul><p><strong><span class=\"kw-alerte\"><span class=\"kw-etio\">Dissection</span> aortique</span></strong></p><p><span class=\"kw-ci\">Anticoagulants à dose curative formellement contre-indiqués</span></p><ul><li><span class=\"kw-ttt\">Normalisation de la pression artérielle</span> (<span class=\"kw-alerte\">urgence</span> hypertensive) : <span class=\"kw-ttt\">β-bloquants</span> ou <span class=\"kw-ttt\">anticalciques</span></li><li><span class=\"kw-def\">Type A</span> (aorte ascendante) → <span class=\"kw-ttt\">chirurgie en urgence</span></li><li><span class=\"kw-def\">Type B</span> → pas de <span class=\"kw-ttt\">chirurgie</span> urgente sans complication, <span class=\"kw-ttt\">contrôle de la pression artérielle</span></li></ul>"},"liensGlobaux":[{"href":"https://www.sfcardio.fr/page/chapitre-6-item-230-douleur-thoracique-aigue","label":"SFC — Chapitre 6 item 230 douleur thoracique aigue"},{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_230_DOULEUR_THORACIQUE_AIGUE_2023-1.pdf","label":"Collège (CEP) — Item 230 douleur thoracique aigue 2023 1"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur thoracique aiguë : détresse vitale (respiratoire / hémodynamique / neurologique) ? — Étape 1 — examen rapide et systématisé, avant tout diagnostic","detail":"<h4>CAT — démarche diagnostique devant une <span class=\"kw-clinique\">douleur thoracique</span> aiguë — Éliminer la <span class=\"kw-alerte\">détresse vitale</span>, puis évoquer les 4 urgences (PIED)</h4>","branches":[{"to":"t-detresse","label":"Oui — au moins un signe de détresse","color":"red"},{"to":"q-profil","label":"Non — patient stable : poursuite de la démarche","color":"blue"}]},{"id":"t-detresse","kind":"terminal","label":"Détresse vitale → SAUV / réanimation","color":"red","detail":"<h4>Reconnaissance</h4><ul><li><span class=\"kw-alerte\">Détresse respiratoire</span> : <span class=\"kw-clinique\">polypnée</span> <span class=\"kw-chiffre\">&gt; 30/min</span> ou <span class=\"kw-clinique\">bradypnée</span> <span class=\"kw-chiffre\">&lt; 10/min</span>, <span class=\"kw-clinique\">tirage</span>, <span class=\"kw-alerte\">désaturation</span> (<span class=\"kw-chiffre\">SpO₂ &lt; 90 %</span>)</li><li><span class=\"kw-alerte\">Détresse hémodynamique</span> : <span class=\"kw-alerte\">arrêt circulatoire</span> ou <span class=\"kw-alerte\">état de choc</span> (<span class=\"kw-clinique\">marbrures</span>, <span class=\"kw-clinique\">oligurie</span>)</li><li><span class=\"kw-alerte\">Atteinte neurologique</span> : <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">agitation</span>, <span class=\"kw-clinique\">convulsions</span></li></ul><h4>Conduite immédiate</h4><ul><li>Prise en charge en <span class=\"kw-alerte\">SAUV / réanimation</span> sans attendre la paraclinique</li><li>Mise en condition : <span class=\"kw-clinique\">scope</span>, <span class=\"kw-bio\">ECG</span> continu, <span class=\"kw-bio\">SpO₂</span>, <span class=\"kw-ttt\">VVP</span>, <span class=\"kw-ttt\">oxygénothérapie</span></li><li><span class=\"kw-ttt\">RCP</span> si arrêt · <span class=\"kw-ttt\">drainage péricardique</span> si <span class=\"kw-alerte\">tamponnade</span> · <span class=\"kw-ttt\">chirurgie</span> si <span class=\"kw-etio\">dissection</span> de type A</li></ul><h4>Renvoi</h4><ul><li>Item 332 (<span class=\"kw-alerte\">état de choc</span>)</li></ul>"},{"id":"q-profil","kind":"decision","label":"Orientation parmi les 4 urgences (PIED) : profil dominant ? — Étape 2 — ECG 18 dérivations + radiographie thoracique + analyse sémiologique de la douleur","branches":[{"to":"q-sca","label":"Douleur constrictive rétrosternale, irradiation, FDRCV (profil ischémique)","color":"red"},{"to":"q-dissection","label":"Douleur transfixiante (coup de poignard, dos), asymétrie tensionnelle / pouls aboli","color":"red"},{"to":"t-ep","label":"Douleur pleurale + dyspnée, contexte thrombo-embolique","color":"amber"},{"to":"t-pericardite","label":"Douleur majorée à l'inspiration / décubitus, sujet jeune ou contage viral","color":"blue"},{"to":"t-autres","label":"Aucun critère des 4 urgences (douleur pariétale, œsophagienne, psychogène...)","color":"green"}]},{"id":"q-sca","kind":"decision","label":"SCA — sus-décalage ST persistant à l'ECG ? — ECG = examen central ; troponines ultrasensibles systématiques","branches":[{"to":"t-sca-st","label":"Oui — sus-ST systématisé","color":"red"},{"to":"t-sca-nst","label":"Non — sous-ST / anomalies T / ECG normal","color":"amber"}]},{"id":"t-sca-st","kind":"terminal","label":"SCA avec sus-décalage ST","color":"red","detail":"<h4><span class=\"kw-imagerie\">ECG</span></h4><ul><li><span class=\"kw-alerte\">Sus-décalage ST</span> persistant systématisé ; signes d'<span class=\"kw-clinique\">ischémie</span> dans un territoire coronaire</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Troponines ultrasensibles</span> élevées avec <span class=\"kw-bio\">cinétique</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">Coronarographie</span> en <span class=\"kw-alerte\">urgence</span> le plus rapidement possible → <span class=\"kw-ttt\">reperfusion</span> (<span class=\"kw-ttt\">angioplastie</span> ± <span class=\"kw-ttt\">stent</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 339 (<span class=\"kw-alerte\">syndrome coronarien aigu</span>)</li></ul>"},{"id":"t-sca-nst","kind":"terminal","label":"SCA sans sus-décalage ST","color":"amber","detail":"<h4><span class=\"kw-imagerie\">ECG</span></h4><ul><li>Sous-décalage ST, anomalies de l'onde T, ou <span class=\"kw-bio\">ECG</span> normal</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Troponines ultrasensibles</span> — la <span class=\"kw-bio\">cinétique</span> est déterminante (apport contributif surtout dans les <span class=\"kw-alerte\">SCA</span> non ST+)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">Coronarographie</span> selon le niveau de risque, dans un délai variable</li></ul><h4>Renvoi</h4><ul><li>Item 339 (<span class=\"kw-alerte\">syndrome coronarien aigu</span>)</li></ul>"},{"id":"q-dissection","kind":"decision","label":"Dissection : stabilité hémodynamique + probabilité clinique ? — Score de probabilité : faible = 0-1, forte = 2-3","branches":[{"to":"t-dissection-urg","label":"Instable, ou stable forte probabilité (score 2-3)","color":"red"},{"to":"t-dissection-explo","label":"Stable, faible probabilité (score 0-1)","color":"amber"}]},{"id":"t-dissection-urg","kind":"terminal","label":"Dissection aortique — confirmation urgente","color":"red","detail":"<h4>Profil</h4><ul><li>Douleur <span class=\"kw-clinique\">transfixiante</span> en <span class=\"kw-clinique\">coup de poignard</span> irradiant dans le <span class=\"kw-clinique\">dos</span> ; <span class=\"kw-clinique\">asymétrie tensionnelle</span> (<span class=\"kw-chiffre\">&gt; 20 mmHg</span>), <span class=\"kw-clinique\">abolition d'un pouls</span> ; <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">syndrome de Marfan</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">ETO</span> (<span class=\"kw-imagerie\">voile intimal</span> pathognomonique) ou <span class=\"kw-imagerie\">angio-TDM thoracique</span> sans délai</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-def\">Type A</span> (aorte ascendante) → <span class=\"kw-ttt\">chirurgie en urgence</span></li><li><span class=\"kw-ttt\">Normalisation de la pression artérielle</span> : <span class=\"kw-ttt\">β-bloquants</span> ou <span class=\"kw-ttt\">anticalciques</span></li><li><span class=\"kw-ci\">Anticoagulants à dose curative formellement contre-indiqués</span></li></ul><h4>Renvoi</h4><ul><li>Item 224 (<span class=\"kw-etio\">HTA</span>) · Item 233 (valvulopathie)</li></ul>"},{"id":"t-dissection-explo","kind":"terminal","label":"Dissection aortique — exploration guidée","color":"amber","detail":"<h4>Situation</h4><ul><li>Probabilité clinique <span class=\"kw-chiffre\">faible (0-1)</span> chez un patient <span class=\"kw-clinique\">hémodynamiquement stable</span></li></ul><h4>Démarche</h4><ul><li><span class=\"kw-imagerie\">ETT/ETO</span> complétée par la <span class=\"kw-imagerie\">radiographie thoracique</span> (<span class=\"kw-imagerie\">élargissement médiastinal</span>) et le dosage des <span class=\"kw-bio\">D-dimères</span> (d'emblée très élevés)</li></ul><h4>Si confirmation</h4><ul><li><span class=\"kw-imagerie\">Angio-TDM thoracique</span> pour le <span class=\"kw-def\">diagnostic positif</span> et la planification chirurgicale ; <span class=\"kw-ci\">anticoagulants curatifs contre-indiqués</span></li></ul><h4>Renvoi</h4><ul><li>Item 224 (<span class=\"kw-etio\">HTA</span>)</li></ul>"},{"id":"t-ep","kind":"terminal","label":"Embolie pulmonaire","color":"amber","detail":"<h4>Profil</h4><ul><li>Douleur <span class=\"kw-clinique\">latéro- ou basithoracique</span>, <span class=\"kw-clinique\">dyspnée</span> ; <span class=\"kw-def\">terrain</span> : âge, comorbidités, <span class=\"kw-etio\">chirurgie récente</span>, <span class=\"kw-etio\">néoplasie</span></li></ul><h4><span class=\"kw-imagerie\">ECG</span></h4><ul><li><span class=\"kw-clinique\">Tachycardie sinusale</span>, <span class=\"kw-clinique\">bloc de branche droit</span>, <span class=\"kw-clinique\">onde T négative</span>, aspect <span class=\"kw-clinique\">S1Q3</span></li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">D-dimères</span> selon la probabilité clinique (bonne valeur prédictive négative) ; <span class=\"kw-bio\">troponine</span> à visée pronostique</li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">Angio-TDM thoracique</span> ; <span class=\"kw-imagerie\">ETT</span> pour le retentissement sur le <span class=\"kw-clinique\">cœur droit</span></li></ul><h4>Renvoi</h4><ul><li>Item 226 (thrombose veineuse profonde - EP)</li></ul>"},{"id":"t-pericardite","kind":"terminal","label":"Péricardite aiguë","color":"blue","detail":"<h4>Profil</h4><ul><li>Sujet <span class=\"kw-etio\">jeune</span>, <span class=\"kw-etio\">contage viral</span> ; douleur majorée à l'<span class=\"kw-clinique\">inspiration</span> et en <span class=\"kw-clinique\">décubitus</span></li></ul><h4><span class=\"kw-imagerie\">ECG</span></h4><ul><li><span class=\"kw-clinique\">Sus-décalage ST concave</span> vers le haut, diffus ; <span class=\"kw-clinique\">sous-décalage du PQ</span></li></ul><h4>Biologie / imagerie</h4><ul><li><span class=\"kw-def\">Syndrome inflammatoire</span> (<span class=\"kw-bio\">CRP</span>) ; <span class=\"kw-imagerie\">ETT</span> : recherche d'un <span class=\"kw-imagerie\">épanchement péricardique</span> et <span class=\"kw-def\">dépistage</span> d'une <span class=\"kw-alerte\">tamponnade</span></li></ul><h4>Renvoi</h4><ul><li>Item 235 (péricardite aiguë)</li></ul>"},{"id":"t-autres","kind":"terminal","label":"Causes non urgentes (après élimination du SCA)","color":"green","detail":"<h4>Causes thoraciques</h4><ul><li><span class=\"kw-etio\">Pneumothorax</span>, <span class=\"kw-etio\">épanchement pleural</span>, <span class=\"kw-etio\">pneumopathie infectieuse</span></li><li><span class=\"kw-etio\">RGO</span> / <span class=\"kw-etio\">spasme œsophagien</span> : peut <span class=\"kw-alerte\">simuler un SCA</span> et être calmé par les <span class=\"kw-ttt\">dérivés nitrés</span> (piège) ; <span class=\"kw-etio\">rupture œsophagienne (Boerhaave)</span></li><li><span class=\"kw-etio\">Syndrome de Tietze</span> (<span class=\"kw-alerte\">douleur reproduite à la palpation</span>), <span class=\"kw-etio\">zona intercostal</span></li></ul><h4>Causes extra-thoraciques</h4><ul><li><span class=\"kw-etio\">Lithiase vésiculaire</span>, <span class=\"kw-etio\">ulcère gastro-duodénal</span>, <span class=\"kw-etio\">pancréatite aiguë</span> ; <span class=\"kw-etio\">douleurs psychogènes</span> (diagnostic d'élimination)</li></ul><h4>Règle</h4><ul><li>On ne retient jamais une cause non urgente <span class=\"kw-alerte\">avant d'avoir éliminé un SCA</span></li></ul><h4>Renvoi</h4><ul><li>Item 360 (pneumothorax) · Item 271 (RGO - hernie hiatale) · Item 358 (pancréatite aiguë)</li></ul>"}]},"cards":[{"i":"386201edcbce","n":230,"o":"230-1","u":"Définition","t":"Connaître la définition d’uune douleur thoracique aiguë","q":"Quelles sont les structures thoraciques potentiellement à l'origine d'une douleur thoracique aiguë et quelles sont les 3 causes les plus fréquentes de cette douleur ?","a":"<ul><li>Les structures potentiellement douloureuses sont : la <strong>paroi thoracique</strong> (incluant côtes, muscles, articulations chondro-costales), les <strong>enveloppes séreuses</strong> (plèvre, péricarde), le <strong>cœur</strong>, l'<strong>œsophage</strong> et l'<strong>aorte</strong>.</li><li>Les 3 causes les plus fréquentes sont le <strong>syndrome coronarien aigu</strong>, les <strong>douleurs œsophagiennes</strong> et les <strong>douleurs psychogènes</strong>.</li></ul>"},{"i":"40b4e18c2a76","n":230,"o":"230-1","u":"Définition","t":"Connaître la définition d’uune douleur thoracique aiguë","q":"Quelle est la définition d'une douleur thoracique aiguë ?","a":"<p>La douleur thoracique aiguë (DTA) est une douleur ressentie dans la <strong>région du thorax</strong>, d'<strong>installation récente</strong>.</p>"},{"i":"5cf06b8caf64","n":230,"o":"230-1","u":"Définition","t":"Connaître la définition d’uune douleur thoracique aiguë","q":"Le parenchyme pulmonaire peut-il être directement à l'origine d'une douleur thoracique aiguë ? Pourquoi ?","a":"<p>Non, le <strong>parenchyme pulmonaire ne fait pas mal</strong> directement car il n'est pas innervé pour la douleur. Seules les pathologies pulmonaires atteignant la <strong>plèvre</strong> peuvent être sources de douleur thoracique.</p>"},{"i":"b10df238011a","n":230,"o":"230-1","u":"Définition","t":"Connaître la définition d’uune douleur thoracique aiguë","q":"Quel est l'objectif prioritaire de la prise en charge initiale d'une douleur thoracique aiguë aux urgences ?","a":"<p>L'objectif prioritaire est d'<strong>éliminer une urgence vitale</strong>.</p>"},{"i":"127fa328f868","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les causes musculo-squelettiques de douleur thoracique aiguë ?","a":"<p>Les causes musculo-squelettiques de douleur thoracique aiguë comprennent :</p><ul><li>Le <strong>syndrome de Tietze</strong> : inflammation du cartilage à la jonction du sternum et d'une ou plusieurs côtes, avec douleur <strong>reproduite par la palpation</strong>.</li><li>Les <strong>lésions osseuses</strong> : lésions sternales, arthralgies chondro-costales, fractures costales (éventuellement pathologiques comme des <strong>métastases</strong> ou un <strong>myélome multiple</strong>).</li><li>Les <strong>douleurs musculo-ligamentaires</strong>.</li></ul>"},{"i":"1b8c0c6ae830","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les causes respiratoires pleuro-pulmonaires de douleur thoracique aiguë, en dehors des urgences cardiovasculaires ?","a":"<p>Les causes respiratoires pleuro-pulmonaires incluent :</p><ul><li>Le <strong>pneumothorax</strong>.</li><li>L'<strong>épanchement pleural</strong>.</li><li>La <strong>pneumopathie infectieuse</strong>, pouvant causer une douleur intense « en coup de poignard » de type pleural en cas de réaction pleurale.</li><li>La <strong>trachéobronchite aiguë</strong>.</li></ul>"},{"i":"5b8290c186a2","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les causes œsophagiennes de douleur thoracique aiguë et leurs particularités sémiologiques ?","a":"<p>Les causes œsophagiennes incluent :</p><ul><li>Le <strong>RGO</strong> et l'<strong>œsophagite</strong> : peuvent simuler un SCA avec une douleur <strong>constrictive</strong> et une <strong>irradiation</strong> (innervation commune cœur/œsophage).</li><li>Le <strong>spasme œsophagien</strong> : douleur d'allure <strong>angineuse</strong>, souvent déclenchée par la <strong>déglutition</strong> et calmée par les <strong>dérivés nitrés</strong> ou le <strong>phloroglucinol</strong>.</li><li>Le <strong>syndrome de Mallory-Weiss</strong>.</li><li>La <strong>rupture de l'œsophage (<span style=\"background-color:#FFD4B2;\">syndrome de Boerhaave</span>)</strong> : associe douleur thoracique, <strong>dyspnée</strong> et <strong>emphysème sous-cutané</strong> (crépitation neigeuse) ou <strong>pneumomédiastin</strong>.</li></ul>"},{"i":"647ff8b4b651","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Comment diagnostique-t-on un pneumothorax ?","a":"<p>Le diagnostic de pneumothorax est posé par une <strong>radiographie thoracique de face en inspiration</strong>, montrant une <strong>hyperclarté</strong> et une <strong>ligne pleurale</strong>. Le cliché en expiration n'est plus recommandé.</p>"},{"i":"9d65d7f8c40e","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quel est le piège diagnostique classique concernant la douleur thoracique aiguë ?","a":"<p>Le piège classique est qu'une douleur d'origine œsophagienne (RGO, spasme) peut parfaitement mimer un <strong>syndrome coronarien aigu (SCA)</strong> et même être calmée par les <strong>dérivés nitrés</strong>. Il est impératif de <strong>toujours éliminer un SCA</strong> avant de conclure à une cause œsophagienne.</p>"},{"i":"bc34ff30667d","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les caractéristiques de la douleur thoracique aiguë en cas de pneumothorax ?","a":"<p>La douleur du pneumothorax est de type <strong>pleural</strong>, c'est-à-dire :</p><ul><li><strong>Latéro-thoracique</strong>.</li><li><strong>Majorée à l'inspiration</strong>.</li></ul><p>À l'examen clinique, on retrouve un <strong>tympanisme</strong> à la percussion et une <strong>abolition du murmure vésiculaire</strong> du côté atteint.</p>"},{"i":"cefca07d068e","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les causes neurologiques et toxiques de douleur thoracique aiguë ?","a":"<p>Les causes neurologiques sont le <strong>zona intercostal</strong> et le <strong>tassement vertébral</strong>. La consommation de <strong>cocaïne</strong> est la principale cause toxique, pouvant entraîner un SCA, un coronarospasme (<strong>angor de Prinzmetal</strong>), une myopéricardite ou un pneumothorax lié aux efforts inspiratoires (sniff).</p>"},{"i":"07556cb34a16","n":230,"o":"230-14","u":"Étiologies","t":"Connaître les principales causes extra-thoraciques de douleur thoracique","q":"Qu'est-ce qu'une douleur thoracique d'origine extra-thoracique ?","a":"<p>Une douleur thoracique d'origine extra-thoracique est une sensation douloureuse ressentie au niveau du thorax, mais dont la cause initiale ou le processus pathologique provient d'organes ou de structures situées <strong>en dehors de la paroi thoracique et des organes intrathoraciques</strong> (cœur, poumons, œsophage). Il ne s'agit donc pas d'une atteinte directe de ces derniers.</p>"},{"i":"8a9ba5c9d53d","n":230,"o":"230-14","u":"Étiologies","t":"Connaître les principales causes extra-thoraciques de douleur thoracique","q":"Quel est le rôle des douleurs psychogènes en tant que cause de douleur thoracique, et comment sont-elles diagnostiquées ?","a":"<p>Les douleurs psychogènes sont une cause <strong>extrêmement fréquente</strong> de douleur thoracique. Elles s'accompagnent souvent d'<strong>angoisse</strong> et s'inscrivent dans un <strong>contexte névrotique</strong>. Elles comptent parmi les 3 causes les plus fréquentes de douleur thoracique aiguë (avec le syndrome coronarien aigu et les douleurs œsophagiennes). Cependant, le diagnostic de douleur psychogène est un <strong>diagnostic d'élimination</strong>, après avoir écarté les urgences vitales et les autres causes organiques.</p>"},{"i":"b0331bd21a6b","n":230,"o":"230-14","u":"Étiologies","t":"Connaître les principales causes extra-thoraciques de douleur thoracique","q":"Quelles sont les principales causes abdominales pouvant provoquer une douleur thoracique projetée ?","a":"<ul><li><strong>Lithiase vésiculaire</strong></li><li><strong>Ulcère gastro-duodénal</strong></li><li><strong>Pancréatite aiguë</strong></li><li><strong>Appendicite sous-hépatique</strong></li><li><strong>Abcès sous-phrénique</strong></li></ul>"},{"i":"0812bdc6e34e","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Quelle est la première étape impérative devant toute douleur thoracique aiguë ?","a":"<p>La première étape impérative, avant même de rechercher la cause, est de rechercher une <strong>détresse vitale</strong> par un examen rapide et systématisé.</p>"},{"i":"3983ada54283","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Quels sont les signes à rechercher devant une suspicion de détresse respiratoire lors d'une douleur thoracique aiguë ?","a":"<ul><li><strong>Fréquence respiratoire</strong> : polypnée (&gt; 30/min) ou bradypnée (&lt; 10/min), voire pause respiratoire.</li><li><strong>Lutte respiratoire</strong> : tirage avec mise en jeu des muscles respiratoires accessoires.</li><li><strong>Retentissement</strong> : sueurs, cyanose, désaturation (<strong>SpO₂ &lt; 90 %</strong>), encéphalopathie respiratoire.</li></ul>"},{"i":"7f0ec527da8b","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Que doit entraîner la découverte d'un seul signe de détresse vitale devant une douleur thoracique aiguë ?","a":"<p>La présence d'un seul de ces signes impose une <strong>prise en charge immédiate</strong> en <strong>salle d'accueil des urgences vitales (SAUV)</strong> ou en réanimation, sans attendre les résultats paracliniques.</p>"},{"i":"bc9c6800184b","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Quels sont les signes à rechercher devant une suspicion d'atteinte neurologique lors d'une douleur thoracique aiguë, indiquant une détresse vitale ?","a":"<ul><li><strong>Troubles de la conscience</strong> : confusion, agitation, convulsions.</li></ul>"},{"i":"d0d2f505b8c7","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Quels sont les signes à rechercher devant une suspicion de détresse hémodynamique lors d'une douleur thoracique aiguë ?","a":"<ul><li><strong>Arrêt circulatoire</strong> : pouls carotidien ou fémoral non perçu, patient inconscient.</li><li><strong>État de choc</strong> : collapsus avec hypoperfusion périphérique, hypotension avec pâleur, marbrures et oligurie.</li><li>Autres signes : signes de <strong>cœur pulmonaire</strong> (rare dans ce contexte), <strong>pouls paradoxal</strong> (dépression du pouls à l'inspiration profonde).</li></ul>"},{"i":"3f0e356d4a32","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques tiques immédiates","q":"Quels sont les signes de gravité et la décision thérapeutique immédiate en cas de dissection aortique de type A ?","a":"<p>Les signes de gravité pouvant évoquer une <strong>dissection aortique de type A</strong> sont l'<strong>asymétrie tensionnelle</strong>, l'<strong>abolition d'un pouls</strong> et un état de <strong>choc</strong>. La décision thérapeutique immédiate est la <strong>chirurgie en urgence</strong>, avec une <strong>contre-indication absolue aux anticoagulants à dose curative</strong>.</p>"},{"i":"4bde727fd742","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques tiques immédiates","q":"Quelle est la conduite à tenir devant un état de choc ou une hypotension persistante lors d'une douleur thoracique grave ?","a":"<p>Devant un état de <strong>choc</strong> ou une <strong>hypotension persistante</strong> lors d'une douleur thoracique grave, la conduite à tenir est l'<strong>orientation en réanimation</strong> et un <strong>traitement étiologique</strong> sans délai.</p>"},{"i":"a591aaa24084","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques tiques immédiates","q":"Quel signe de gravité oriente vers une tamponnade cardiaque et quelle est la décision thérapeutique immédiate ?","a":"<p>Le signe de gravité orientant vers une <strong>tamponnade cardiaque</strong> est l'association <strong>pouls paradoxal</strong>, <strong>turgescence jugulaire</strong> et <strong>hypotension</strong>. La décision thérapeutique immédiate est un <strong>drainage péricardique en urgence</strong>.</p>"},{"i":"de6f099af09c","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques tiques immédiates","q":"Quelle est la décision thérapeutique immédiate en cas de pouls non perçu et d'inconscience (arrêt circulatoire) devant une douleur thoracique grave ?","a":"<p>En cas d'<strong>arrêt circulatoire</strong> (pouls non perçu, inconscience) devant une douleur thoracique grave, la décision thérapeutique immédiate est la <strong>réanimation cardio-pulmonaire</strong> et l'appel du réanimateur.</p>"},{"i":"df0d1a15c4c1","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques tiques immédiates","q":"Quelle est la prise en charge immédiate devant une douleur thoracique avec signes de gravité, avant même le diagnostic étiologique ?","a":"<p>Devant une douleur thoracique avec signes de gravité, la prise en charge immédiate, menée en parallèle de l'évaluation, comprend :</p><ul><li>Mise en condition immédiate avec <strong>scope ECG continu</strong>, monitorage de la <strong>pression artérielle</strong> et de la <strong>SpO₂</strong>.</li><li>Pose d'une <strong>voie veineuse périphérique</strong>.</li><li><strong>Oxygénothérapie</strong> en cas de désaturation.</li><li>Prise en charge en salle d'accueil des urgences vitales (<strong>SAUV</strong>), à proximité immédiate d'un <strong>chariot d'urgence</strong> et d'un <strong>défibrillateur</strong>.</li></ul>"},{"i":"e20995ab2899","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques tiques immédiates","q":"Quels sont les signes de gravité généraux d'une douleur thoracique aiguë nécessitant des décisions thérapeutiques immédiates ?","a":"<p>Les signes de gravité généraux d'une douleur thoracique aiguë nécessitant des décisions thérapeutiques immédiates sont les signes de <strong>détresse vitale</strong> :</p><ul><li><strong>Détresse respiratoire</strong></li><li><strong>Détresse hémodynamique</strong></li><li><strong>Détresse neurologique</strong></li></ul>"},{"i":"29beedf231fa","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quels sont les principaux critères permettant de distinguer sémiologiquement une douleur thoracique d'origine ischémique (syndrome coronarien aigu) d'une douleur non ischémique ?","a":"<p>La distinction sémiologique entre une douleur ischémique et non ischémique repose sur les critères suivants :</p><ul><li><strong>Caractéristiques</strong> :<ul><li><strong>Ischémique</strong> : <strong>constriction</strong>, <strong>pesanteur</strong>, brûlure.</li><li><strong>Non ischémique</strong> : acérée, en coup de poignard, augmentée par la respiration.</li></ul></li><li><strong>Siège et irradiation</strong> :<ul><li><strong>Ischémique</strong> : <strong>rétrosternal</strong>, médiothoracique, irradiant cou, épaules, avant-bras, mâchoire ; souvent associé à <strong>sueurs</strong> et <strong>nausées</strong>.</li><li><strong>Non ischémique</strong> : sous-mammaire gauche, hémithorax gauche, punctiforme (montré du doigt) ; dorsal (suggérant une dissection).</li></ul></li><li><strong>Facteurs déclenchants</strong> :<ul><li><strong>Ischémique</strong> : <strong>effort</strong>, stress, énervement, temps froid.</li><li><strong>Non ischémique</strong> : après la fin de l'effort, soulagement par l'effort, ou provoquée par un mouvement particulier du corps.</li></ul></li><li><strong>Durée</strong> :<ul><li><strong>Ischémique</strong> : <strong>minutes</strong>.</li><li><strong>Non ischémique</strong> : <strong>secondes</strong>, ou heures (en l'absence d'élévation des troponines).</li></ul></li></ul>"},{"i":"58e83eb42bf0","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quel profil clinique doit faire évoquer une dissection aortique, en termes de terrain, mode de survenue, horaire, localisation et type de douleur ?","a":"<p>Le profil clinique évocateur d'une <strong>dissection aortique</strong> est le suivant :</p><ul><li><strong>Terrain</strong> : Présence de <strong>FDR cardiovasculaires</strong>, particulièrement l'<strong>HTA</strong> (hypertension artérielle).</li><li><strong>Mode de survenue</strong> : <strong>Brutal</strong>.</li><li><strong>Horaire</strong> : Généralement au repos.</li><li><strong>Localisation et irradiation</strong> : Douleur <strong>rétrosternale</strong>, souvent <strong>transfixiante</strong> (irradiant dans le dos).</li><li><strong>Type</strong> : Douleur en <strong>coup de poignard</strong>.</li></ul>"},{"i":"677623c9ded4","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quel profil clinique doit faire évoquer une embolie pulmonaire, en termes de terrain, mode de survenue, horaire, localisation et type de douleur ?","a":"<p>Le profil clinique évocateur d'une <strong>embolie pulmonaire</strong> est le suivant :</p><ul><li><strong>Terrain</strong> : Âge avancé, <strong>comorbidités</strong> (cancer, insuffisance cardiaque), <strong>chirurgie récente</strong>, <strong>néoplasie</strong>.</li><li><strong>Mode de survenue</strong> : Plutôt <strong>progressif</strong>, souvent associé à une <strong>dyspnée</strong>.</li><li><strong>Horaire</strong> : Au repos.</li><li><strong>Localisation et irradiation</strong> : Douleur <strong>latéro-</strong> ou <strong>basithoracique</strong>.</li><li><strong>Type</strong> : Souvent de type <strong>constrictive</strong>.</li></ul>"},{"i":"7c6c692aa2b0","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quel profil clinique doit faire évoquer un Syndrome Coronarien Aigu (SCA), en termes de terrain, mode de survenue, horaire, localisation et type de douleur ?","a":"<p>Le profil clinique évocateur d'un <strong>Syndrome Coronarien Aigu (SCA)</strong> est le suivant :</p><ul><li><strong>Terrain</strong> : Présence de <strong>FDR cardiovasculaires</strong> (facteurs de risque).</li><li><strong>Mode de survenue</strong> : Généralement <strong>brutal</strong>.</li><li><strong>Horaire</strong> : Peut survenir à l'effort ou au repos.</li><li><strong>Localisation et irradiation</strong> : Douleur <strong>rétrosternale</strong>, pouvant irradier à l'épigastre, la mâchoire, les bras ou être interscapulaire.</li><li><strong>Type</strong> : Douleur <strong>constrictive</strong> ou de type <strong>brûlure</strong>.</li></ul>"},{"i":"aec287e91eeb","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Face à une douleur thoracique aiguë, quelles sont les quatre urgences cardiovasculaires vitales à évoquer systématiquement, selon le moyen mnémotechnique PIED ?","a":"<p>Devant une douleur thoracique aiguë, les <strong>quatre urgences cardiovasculaires vitales</strong> à évoquer systématiquement, regroupées sous le moyen mnémotechnique PIED, sont :</p><ul><li><strong>P</strong> : <strong>Péricardite</strong></li><li><strong>I</strong> : <strong>Infarctus</strong> (syndrome coronarien aigu - SCA)</li><li><strong>E</strong> : <strong>Embolie pulmonaire</strong></li><li><strong>D</strong> : <strong>Dissection aortique</strong></li></ul>"},{"i":"cdf8f6250822","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quel profil clinique doit faire évoquer une péricardite, en termes de terrain, mode de survenue, horaire, localisation et type de douleur ?","a":"<p>Le profil clinique évocateur d'une <strong>péricardite</strong> est le suivant :</p><ul><li><strong>Terrain</strong> : Généralement <strong>sujet jeune</strong>, souvent précédé d'un <strong>contage viral</strong>.</li><li><strong>Mode de survenue</strong> : <strong>Aigu</strong>.</li><li><strong>Horaire</strong> : Souvent aggravée à l'inspiration et en décubitus.</li><li><strong>Localisation et irradiation</strong> : Douleur <strong>rétrosternale</strong>.</li><li><strong>Type</strong> : Douleur de type <strong>constrictive</strong>.</li></ul>"},{"i":"ed4aa35c8c3f","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quelles sont les plaintes cardinales qu'il est indispensable de renseigner systématiquement pour toute urgence cardiovasculaire devant une douleur thoracique ?","a":"<p>Indépendamment de l'urgence cardiovasculaire évoquée devant une douleur thoracique, quatre plaintes cardinales doivent être systématiquement renseignées :</p><ul><li>La <strong>douleur thoracique</strong> elle-même.</li><li>La <strong>dyspnée</strong>.</li><li>La <strong>syncope</strong>.</li><li>Les <strong>palpitations</strong>.</li></ul>"},{"i":"1fa618406c45","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de le dissection aortique","q":"Quels sont les signes physiques à rechercher lors de l'examen clinique d'une dissection aortique ?","a":"<p>Les signes physiques d'une dissection aortique sont :</p><ul><li>Une <strong>asymétrie tensionnelle</strong> (différence > <strong>20 mmHg</strong> entre les deux bras).</li><li>L'<strong>abolition d'un pouls</strong>.</li><li>Un <strong>souffle d'insuffisance aortique</strong> (présent dans <strong>50 % des dissections de type A</strong>).</li><li>Une <strong>poussée d'HTA</strong> ou, au contraire, une <strong>hypotension/choc</strong>.</li></ul>"},{"i":"2374757417bb","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de le dissection aortique","q":"Quelles sont les complications possibles d'une dissection aortique, parfois révélatrices ?","a":"<p>Les complications, parfois révélatrices, d'une dissection aortique par extension du faux chenal aux collatérales sont :</p><ul><li>Un <strong>déficit neurologique</strong> (AVC).</li><li>Un <strong>infarctus médullaire</strong> (syndrome médullaire aigu).</li><li>Un <strong>hémopéricarde avec tamponnade</strong>.</li><li>Un <strong>infarctus mésentérique</strong>.</li><li>Une <strong>ischémie aiguë d'un membre</strong>.</li><li>Une <strong>insuffisance rénale aiguë</strong>.</li></ul>"},{"i":"5a80a1907088","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de le dissection aortique","q":"Quels sont les facteurs de risque et les terrains favorisants d'une dissection aortique ?","a":"<p>Les facteurs de risque et terrains favorisants d'une dissection aortique sont :</p><ul><li>Une <strong>HTA ancienne</strong> et l'<strong>athérome</strong>, retrouvés principalement chez le sujet âgé (en général > 60 ans).</li><li>Des syndromes génétiques tels que le <strong>syndrome de Marfan</strong> ou d'<strong>Ehlers-Danlos</strong>, rencontrés chez le sujet plus jeune.</li><li>Un <strong>antécédent familial de maladie aortique</strong>.</li><li>Un <strong>anévrisme de l'aorte thoracique</strong> ou une <strong>valvulopathie aortique connue</strong>.</li><li>Un <strong>antécédent de chirurgie aortique</strong>.</li></ul>"},{"i":"8b8ea39e5c55","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de le dissection aortique","q":"Quelle est la valeur diagnostique d'un score clinique de probabilité pour la dissection aortique ?","a":"<p>Le score clinique de probabilité pour la dissection aortique est basé sur 3 critères, chacun valant 1 point :</p><ul><li><strong>Terrain évocateur</strong> (syndrome de Marfan, ATCD familial de maladie aortique, anévrisme ou valvulopathie aortique connus, ATCD de chirurgie aortique).</li><li><strong>Douleur évocatrice</strong> (thoracique, dorsale ou abdominale, brutale, intense, à type de déchirement).</li><li><strong>Signes physiques</strong> (abolition d'un pouls, asymétrie tensionnelle, déficit neurologique focal, insuffisance aortique, hypotension ou choc).</li></ul><p>La probabilité clinique est jugée <strong>faible si le score est de 0 ou 1</strong>, et <strong>forte si le score est de 2 ou 3</strong>.</p>"},{"i":"9e15da0f1a7a","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de le dissection aortique","q":"Quels sont les signes fonctionnels évocateurs d'une dissection aortique ?","a":"<p>Le signe fonctionnel principal d'une dissection aortique est la douleur, caractérisée par :</p><ul><li>Un début <strong>aigu et brutal</strong>.</li><li>Une nature <strong>intense</strong>, à type de <strong>déchirement</strong> ou en <strong>coup de poignard</strong> (transfixiante).</li><li>Une <strong>irradiation dans le dos</strong>, souvent <strong>migratrice</strong>, descendant vers les lombes et les membres inférieurs.</li><li>Parfois accompagnée d'une <strong>syncope</strong>.</li></ul>"},{"i":"c81fc7fb0972","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de le dissection aortique","q":"Quelle est la contre-indication majeure à connaître en cas de suspicion de dissection aortique, et pourquoi ?","a":"<p>En cas de dissection aortique, les <strong>anticoagulants à dose curative sont formellement contre-indiqués</strong>.</p><p>Cette interdiction absolue est cruciale pour ne pas aggraver les saignements au niveau du faux chenal, ce qui fait tout l'enjeu de ne pas confondre une dissection avec un SCA ou une embolie pulmonaire, qui eux nécessiteraient une anticoagulation.</p>"},{"i":"16fe69436990","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quelles sont les classifications de la dissection aortique de Stanford et DeBakey ?","a":"<p>Les classifications de la dissection aortique sont :</p><ul><li><strong>Stanford :</strong><ul><li><strong>Type A :</strong> Atteinte de l'aorte ascendante.</li><li><strong>Type B :</strong> Aorte ascendante respectée (dissection limitée à l'aorte descendante).</li></ul></li><li><strong>DeBakey :</strong><ul><li><strong>Type I :</strong> Porte d'entrée sur l'aorte ascendante avec extension à l'aorte descendante.</li><li><strong>Type II :</strong> Limitée à l'aorte ascendante.</li><li><strong>Type III :</strong> Porte d'entrée après l'artère sous-clavière gauche.</li></ul></li></ul>"},{"i":"6eccc68b7e10","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quelle est la première étape systématique de la démarche diagnostique face à une douleur thoracique aiguë ?","a":"<p>La première étape est la recherche systématique et rapide d'une <strong>détresse vitale</strong> : respiratoire, hémodynamique ou neurologique.</p>"},{"i":"78372a68acfd","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quels sont les examens paracliniques de première intention systématiques devant toute douleur thoracique aiguë ?","a":"<p>Les examens paracliniques de première intention systématiques sont :</p><ul><li>L'<strong>ECG 18 dérivations</strong></li><li>La <strong>radiographie thoracique</strong> en inspiration</li><li>La mesure de la <strong>SpO₂</strong> (saturation pulsée en oxygène), éventuellement complétée par les gaz du sang</li></ul>"},{"i":"a19563e9745e","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quel examen est un signe pathognomonique de la dissection aortique et quels sont les avantages principaux de l'angio-scanner thoracique ?","a":"<p>L'<strong>ETO</strong> (échographie transœsophagienne) met en évidence le <strong>voile intimal</strong>, signe pathognomonique de la dissection aortique.</p><p>L'<strong>angio-TDM thoracique</strong> (angio-scanner) est souvent nécessaire au diagnostic positif (surtout chez les patients instables) et crucial pour la <strong>planification chirurgicale</strong> (porte d'entrée, extension de la dissection, atteinte des troncs supra-aortiques, mésentériques ou rénaux).</p>"},{"i":"cebef01e68d8","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quelles sont les quatre urgences cardiovasculaires à évoquer systématiquement devant une douleur thoracique, selon l'acronyme PIED ?","a":"<p>Les quatre urgences cardiovasculaires à évoquer sont :</p><ul><li><strong>P</strong>éricardite</li><li><strong>I</strong>nfarctus du myocarde (syndrome coronarien aigu)</li><li><strong>E</strong>mbolie pulmonaire</li><li><strong>D</strong>issection aortique</li></ul>"},{"i":"ec97c5461f4a","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quelle est la démarche diagnostique par imagerie et biologie en cas de suspicion de dissection aortique chez un patient stable avec une faible probabilité clinique ?","a":"<p>Chez un patient stable avec une probabilité clinique faible (score 0-1), la démarche inclut une <strong>ETT/ETO</strong> (échographie transthoracique/transœsophagienne) complétée par la <strong>radiographie thoracique</strong> (recherche d'un élargissement médiastinal) et le dosage des <strong>D-dimères</strong> (qui sont d'emblée très élevés en cas de dissection).</p>"},{"i":"20ce0974d045","n":230,"o":"230-7","u":"Examens complémentaires","t":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","q":"Quelles anomalies électrocardiographiques caractérisent un syndrome coronarien aigu (SCA) ?","a":"<p>Les anomalies ECG évocatrices d'un SCA sont :</p><ul><li>Un <strong>sus-décalage ST</strong>.</li><li>Un <strong>sous-décalage ST</strong>.</li><li>Des anomalies de l'<strong>onde T</strong> (négative, pointue, etc.).</li></ul>"},{"i":"27684a310466","n":230,"o":"230-7","u":"Examens complémentaires","t":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","q":"Quel est l'apport de l'électrocardiogramme (ECG) dans le diagnostic d'une dissection aortique et quels sont ses pièges ?","a":"<p>L'ECG est généralement <strong>peu contributif</strong> dans le diagnostic de dissection aortique et est le plus souvent <strong>normal</strong>. Cependant, en cas d'extension de la dissection à une artère coronaire, l'ECG peut mimer un <strong>syndrome coronarien aigu (SCA)</strong>, présentant un sous-décalage ST, un sus-décalage ST ou une inversion de l'onde T. Le piège est qu'un ECG d'allure de SCA n'élimine pas une dissection aortique, exposant au risque d'<strong>anticoaguler à tort</strong> une dissection.</p>"},{"i":"9574c6037dfb","n":230,"o":"230-7","u":"Examens complémentaires","t":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","q":"Quelles sont les anomalies électrocardiographiques typiques de la péricardite aiguë ?","a":"<p>L'ECG d'une péricardite aiguë est caractérisé par :</p><ul><li>Un <strong>sus-décalage ST concave vers le haut</strong>, généralement <strong>diffus</strong>.</li><li>Un <strong>sous-décalage du segment PQ</strong>.</li></ul>"},{"i":"d976cd17ded3","n":230,"o":"230-7","u":"Examens complémentaires","t":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","q":"Quelles anomalies électrocardiographiques observe-t-on en cas d'embolie pulmonaire ?","a":"<p>En cas d'embolie pulmonaire, l'ECG peut montrer :</p><ul><li>Une <strong>tachycardie sinusale</strong>.</li><li>Un <strong>bloc de branche droit</strong>.</li><li>Des <strong>ondes T négatives</strong>.</li><li>Un aspect <strong>S1Q3</strong> (onde S en D1, onde Q en D3, et onde T négative en D3 est parfois précisé).</li></ul>"},{"i":"0c3a698d9d3d","n":230,"o":"230-8","u":"Examens complémentaires","t":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","q":"Quelle est la valeur de la radiographie thoracique en cas de suspicion d'embolie pulmonaire ou de péricardite aiguë ?","a":"<ul><li>Pour l'<strong>embolie pulmonaire</strong>, la radiographie thoracique est <strong>souvent normale</strong>. Les signes sont inconstants et peu spécifiques, et ne permettent pas de confirmer ni d'exclure le diagnostic.</li><li>Pour la <strong>péricardite</strong>, la radiographie est <strong>normale en règle générale</strong>. Une <strong>cardiomégalie</strong> peut être visible uniquement en cas d'épanchement péricardique abondant.</li></ul>"},{"i":"181eb250b540","n":230,"o":"230-8","u":"Examens complémentaires","t":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","q":"Quelle est la place générale de la radiographie thoracique dans l'évaluation d'une douleur thoracique aiguë, en particulier vis-à-vis des urgences cardiovasculaires ?","a":"<p>La radiographie thoracique est un examen <strong>systématique</strong> réalisé en inspiration. Sa principale utilité est d'<strong>écarter les diagnostics différentiels</strong> tels que le pneumothorax, la pneumopathie ou l'épanchement pleural. Elle peut apporter des signes d'orientation, mais est souvent <strong>normale</strong> dans les urgences cardiovasculaires proprement dites.</p>"},{"i":"49b8e6deac07","n":230,"o":"230-8","u":"Examens complémentaires","t":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","q":"Quels signes radiologiques thoraciques peuvent orienter vers une dissection aortique ?","a":"<p>Devant une suspicion de dissection aortique, la radiographie thoracique peut montrer :</p><ul><li>Un <strong>élargissement du médiastin supérieur</strong> (signe le plus fréquent).</li><li>Un éventuel <strong>épanchement pleural</strong> (hémothorax en cas de rupture aortique).</li><li>Un <strong>double contour aortique</strong> peut parfois être visible.</li></ul>"},{"i":"6d4e50d5f518","n":230,"o":"230-8","u":"Examens complémentaires","t":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","q":"Quelles sont les anomalies à rechercher à la radiographie thoracique en cas de syndrome coronaire aigu (SCA) avec douleur thoracique ?","a":"<p>En cas de SCA, la radiographie thoracique est <strong>normale en règle générale</strong>, car il n'y a pas de signe radiologique spécifique de l'infarctus. Cependant, elle peut rechercher des signes d'<strong>insuffisance cardiaque</strong> (ex: œdème pulmonaire).</p>"},{"i":"1b7faa7e41b0","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Quels bilans biologiques complémentaires sont requis en cas de suspicion de dissection aortique, en dehors des troponines et D-dimères ?","a":"<p>En sus des troponines et D-dimères, le bilan biologique requis en cas de dissection aortique comprend également :</p><ul><li><strong>NFS-plaquettes</strong></li><li><strong>CRP</strong> (syndrome inflammatoire)</li><li><strong>Créatininémie</strong></li><li><strong>Créatine-kinase (CK)</strong> pour la recherche de rhabdomyolyse.</li></ul>"},{"i":"32ba648a7dfd","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Dans quelles situations de douleur thoracique aiguë les D-dimères ont-ils une utilité diagnostique et quelle est leur principale valeur ?","a":"<p>Les D-dimères sont d'emblée très élevés en cas de <strong>dissection aortique</strong>. Dans l'<strong>embolie pulmonaire</strong>, leur dosage se fait selon la probabilité clinique. Leur principale valeur est <strong>prédictive négative</strong> : des D-dimères négatifs associés à une probabilité clinique faible écartent le diagnostic d'embolie pulmonaire.</p>"},{"i":"81dfd728d250","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Dans quel contexte de douleur thoracique aiguë les troponines ultrasensibles sont-elles surtout contributives, et peuvent-elles être élevées dans une péricardite ?","a":"<p>Les troponines ultrasensibles sont surtout contributives dans les <strong>Syndromes Coronariens Aigus sans sus-décalage du segment ST (SCA non ST+)</strong>, où leur élévation avec cinétique permet d'affirmer le diagnostic de SCA. Dans la péricardite, une élévation des troponines est possible si une <strong>myocardite</strong> est associée.</p>"},{"i":"e20dfa671cdf","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Quels sont les deux examens biologiques fondamentaux à la démarche diagnostique devant une douleur thoracique aiguë ?","a":"<p>Les deux examens biologiques structurant le bilan initial sont les <strong>troponines ultrasensibles</strong> et les <strong>D-dimères</strong>.</p>"},{"i":"e5e6e9c232a6","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Quelle est l'interprétation d'une élévation des troponines ultrasensibles en contexte de douleur thoracique aiguë ?","a":"<p>Une élévation des troponines ultrasensibles signe une <strong>souffrance myocardique</strong>, mais n'est pas spécifique d'un Syndrome Coronarien Aigu (SCA). Elle peut aussi être élevée en cas de <strong>pneumbolie pulmonaire (EP)</strong>, de <strong>dissection aortique</strong>, de <strong>myocardite</strong>. La <strong>cinétique</strong> (évolution dans le temps) et le <strong>contexte clinique</strong> sont essentiels à l'interprétation.</p>"}]};